function selectGrapplePoint(){const p=player.position,dir=forward();let best=null,score=Infinity;for(const point of rooftopPoints){const dx=point.position.x-p.x,dz=point.position.z-p.z,d=Math.hypot(dx,dz),dot=d?(dx*dir.x+dz*dir.z)/d:1;if(d>4&&d<42&&dot>.12){const s=d-dot*8;if(s<score){score=s;best=point}}}grappleTarget=best;for(const point of rooftopPoints)point.mesh.visible=point===best;$('#target-reticle').classList.toggle('hidden',!best||grappleTime>0);return best}
