function spawnCaseThreat(){for(const e of enemies){const group=e.mesh.userData.group;e.alive=storyStage===0?group===0:storyStage===3?group===1:false;e.mesh.visible=e.alive;e.health=e.max;e.alert=false}for(const a of actors.filter(a=>a.type==='villain')){a.alive=false;a.mesh.visible=false}const h=hideoutForStage(storyStage);if(h){h.mesh.visible=true;const actorTarget=actors.find(a=>a.name===h.name);if(actorTarget){actorTarget.alive=true;actorTarget.health=100;actorTarget.mesh.visible=true;actorTarget.alert=false}activate(h.name);const mark=markers.find(m=>m.name===h.name);if(mark){mark.x=h.x;mark.z=h.z;mark.active=true}}else activate(storyStage===0||storyStage===3?'GANG DISTRICT':'CASE CLUES');}
function completeCaseStage(){const was=storyStage;if(storyStage===0){storyStage=1;caseEvidence=0;toast('CRIME SCENE SECURED · EVIDENCE TRAIL OPEN');talk([['ROBIN','The crew’s calling card matches the Riddler. We need evidence from across Gotham to find his separate hideout.'],['ALFRED','I have logged the clue trail, including a witness statement from the East End. Return to the Batcomputer whenever you need a briefing.']],updateObjective)}else if(storyStage===1){storyStage=2;toast('HIDEOUT DISCOVERED · RIDDLER');talk([['BATCOMPUTER','Pattern match complete. The Riddler’s hideout has been located.'],['ROBIN','Separate hideout, separate trap. Let’s move carefully.']],updateObjective)}else if(storyStage===2){storyStage=3;toast('RIDDLER APPREHENDED · MOB CASE UNLOCKED');talk([['ROBIN','His files point to a Falcone weapons transfer. The mob is using the East Docks.'],['ALFRED','A witness report and security stills are attached to the new case.']],updateObjective)}else if(storyStage===3){storyStage=4;toast('MOB OPERATION DISRUPTED · LEDGER RECOVERED');talk([['BATCOMPUTER','The ledger reveals Penguin’s Iceberg Lounge as the mob’s laundering front.'],['ALFRED','Cobblepot’s hideout is now marked. The evidence is preserved in the case archive.']],updateObjective)}else if(storyStage===4){storyStage=5;toast('PENGUIN APPREHENDED · IVY CASE UNLOCKED');talk([['ROBIN','The Penguin’s shipment logs lead to poisoned soil at the botanical gardens.'],['BATCOMPUTER','Chemical signatures identify Poison Ivy. Her hideout has been isolated.']],updateObjective)}else if(storyStage===5){storyStage=6;talk([['BATCOMPUTER','Ivy’s samples trace back to a stolen cryogenic core at GothCorp.'],['ALFRED','Mr. Freeze’s laboratory is located. I have added the access route to the map.']],updateObjective)}else if(storyStage===6){storyStage=7;talk([['ROBIN','Freeze’s data names the Joker. He’s preparing something at the old Monarch Theater.'],['BATCOMPUTER','Final case authorized. Joker’s hideout is the last active lead.']],updateObjective)}else{storyStage=8;boss=null;activate('');$('#bossbar').classList.add('hidden');$('#ending-title').textContent='GOTHAM STILL STANDS.';$('#ending-copy').textContent=`The Joker’s final act is stopped. ${challengeCount()} Gotham challenges recovered. Mission reports, witnesses, and evidence are archived in the Batcave.`;$('#ending-screen').classList.remove('hidden');paused=true;updateObjective();return}if(was<7){missionDeployed=false;inCave=true;player.position.set(150,0,11);robin.position.set(147.5,0,9);bat.position.set(150,0,11);$('#mode-label').textContent='BATCAVE HEADQUARTERS';setObjective('Return to the Batcomputer to review the case and select your next patrol.','CASE FILE UPDATED',100,100,'CASE REPORT · SAVED AT HEADQUARTERS');}}
function progress(){if(mode!=='story')return;if(storyStage===0&&gangDown>=5){gangDown=5;completeCaseStage()}else if(storyStage===1&&caseEvidence>=8){completeCaseStage()}else if(storyStage===2&&boss?.health<=0){completeCaseStage()}else if(storyStage===3&&gangDown>=10){completeCaseStage()}else if(storyStage>=4&&storyStage<=7&&boss?.health<=0){completeCaseStage()}updateObjective()}
function updateObjective(){if(mode==='villain'){setObjective('Defeat Batman and Robin. Swap villains with Q.','VILLAIN RAMPAGE · '+villains[selected],100-heroHealth,100,`HERO VITALS ${heroHealth}%`);return}if(inCave){setObjective(storyStage>=8?'Gotham is safe tonight. The case is yours to replay.':'Report to the Batcomputer, review crime alerts, and prepare for patrol.',storyStage>=8?'CASE FILE CLOSED':'BATCAVE · HEADQUARTERS',storyStage,8,'HEADQUARTERS · CASE FILES / SUIT STATION / VEHICLE BAY');return}setObjective(currentCaseObjective(),storyStage>=7?'THE JOKER · FINAL ACT':`GOTHAM PATROL · CASE ${String(storyStage+1).padStart(2,'0')}`,storyStage===1?caseEvidence:boss?.health??gangDown,storyStage===1?8:storyStage===0?5:100,storyStage===1?`${caseEvidence} / 8 evidence scans · ${challengeCount()} challenges`:storyStage===0?`${Math.min(gangDown,5)} / 5 crew stopped`:storyStage===3?`${Math.max(0,10-gangDown)} mob operatives remain`:`${hideoutForStage(storyStage)?.name||'ACTIVE CASE'} · INVESTIGATION / CONFRONTATION`)}
function interact(){if(dialogueLock||!gameStarted)return;if(currentRiddle){return}if(ride){leaveVehicle();return}const p=player.position;if(inCave){if(Math.hypot(p.x-150,p.z+8)<5){openCaseFiles();return}if(Math.hypot(p.x-150,p.z-8)<5){openGarage();return}if(Math.hypot(p.x-139,p.z+1)<3.5){toast('SUIT STATION · ARMORED SUITS READY FOR BATMAN & ROBIN');return}if(Math.hypot(p.x-161,p.z+1)<3.5){toast('GADGET LAB · BATARANGS, SMOKE PELLETS, GRAPPLE, AND WING-DISCS');return}const a=nearestActor(3.2);if(a&&a.lines?.length){talk(a.lines,updateObjective);return}if(Math.hypot(p.x-150,p.z-13)<4){toast('CHECK IN AT THE BATCOMPUTER BEFORE DEPARTING');return}toast('THE BATCAVE IS YOUR PERMANENT HEADQUARTERS · USE THE BATCOMPUTER TO DEPLOY');return}if(Math.hypot(p.x,p.z+12)<4.5){returnToCave();return}const riddleNear=riddles.find(r=>!r.solved&&Math.hypot(p.x-r.mesh.position.x,p.z-r.mesh.position.z)<3);if(riddleNear){openRiddle(riddleNear);return}const actorNear=nearestActor(3.2);if(actorNear&&actorNear.lines?.length){talk(actorNear.lines,()=>{caseEvidence++;toast('WITNESS STATEMENT ADDED TO CASE FILE');progress()});return}if(storyStage===1||storyStage===5||storyStage===6){const clue=evidence.find(e=>!e.found);if(clue)toast('SCAN THE GLOWING EVIDENCE MARKERS TO COLLECT A CRIME-SCENE LEAD');return}if(storyStage===0||storyStage===3)toast('STOP THE ACTIVE CRIMINAL CREW');else toast('FOLLOW THE DISCOVERED HIDEOUT MARKER');}
function updateInteraction(){let text='';const p=player.position;if(inCave){if(Math.hypot(p.x-150,p.z+8)<5)text='[ E ]  OPEN BATCOMPUTER · CASE FILES';else if(Math.hypot(p.x-150,p.z-8)<5)text='[ E ]  OPEN VEHICLE BAY';else if(Math.hypot(p.x-139,p.z+1)<3.5)text='[ E ]  SUIT & ARMOR STATION';else if(Math.hypot(p.x-161,p.z+1)<3.5)text='[ E ]  GADGET LAB';else if(nearestActor(3.2))text='[ E ]  SPEAK WITH ALFRED';else if(Math.hypot(p.x-150,p.z-13)<4)text='[ E ]  ELEVATOR · DISPATCH FROM BATCOMPUTER'}else if(Math.hypot(p.x,p.z+12)<4.5)text='[ E ]  RETURN TO THE BATCAVE';else if(!missionDeployed)text='RETURN TO THE BATCAVE ELEVATOR';else if(riddles.some(r=>!r.solved&&Math.hypot(p.x-r.mesh.position.x,p.z-r.mesh.position.z)<3))text='[ E ]  REVIEW SECURITY FOOTAGE';else if(nearbyRide(4))text='[ E ]  ENTER VEHICLE';else if(nearestActor(3.2))text='[ E ]  QUESTION WITNESS';else if(evidence.some(e=>!e.found&&Math.hypot(p.x-e.mesh.position.x,p.z-e.mesh.position.z)<2))text='[ E ]  SCAN CRIME SCENE EVIDENCE';$('#interaction').textContent=text;$('#interaction').classList.toggle('show',!!text)}
$('#start-button').onclick=()=>{$('#start-screen').classList.add('hidden');gameStarted=true;inCave=true;missionDeployed=false;player=bat;companion=robin;player.position.set(150,0,1);robin.position.set(147.5,0,2.4);batmobile.position.set(145,0,8);bike.position.set(155,0,8);garage.position.set(150,0,8);$('#mode-label').textContent='BATCAVE HEADQUARTERS';$('#hero-name').textContent='THE BAT';$('#hero-avatar').textContent='B';talk([['ALFRED','Welcome to the Batcave, sir. Gotham’s police band has flagged several crimes. The Batcomputer holds the case files; your suit and equipment are ready, and the Batmobile and Robin’s motorcycle are in the vehicle bay.'],['ROBIN','We start here, work the evidence, and come back here to file every report. Let’s see what Gotham needs.']],()=>{updateObjective();toast('BATCAVE ONLINE · REVIEW THE BATCOMPUTER')})};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#case-screen').classList.contains('hidden')){$('#case-screen').classList.add('hidden');paused=false}});
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock3.getDelta(),.04);updateTransit(dt);if(gameStarted&&!paused){gameTime+=dt;pollGamepad(dt);stepGadgets(dt);if(!dialogueLock&&!currentRiddle){move(dt);moveCompanion(dt);enemiesThink(dt);collect();updateInteraction();attackCooldown=Math.max(0,attackCooldown-dt);damageTimer=Math.max(0,damageTimer-dt);if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){combo=0;$('#combo').classList.remove('show')}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}for(const e of evidence)if(!e.found){e.mesh.rotation.y+=dt*.7;e.mesh.position.y=.12+Math.sin(gameTime*2+e.id)*.12}for(const m of markers){m.mesh.rotation.y+=dt*.35;m.mesh.visible=m.active||m.name==='GANG DISTRICT'&&storyStage===0}}}cameraUpdate(dt);showBoss();renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.6))});
activate('GANG DISTRICT');setHealth();updateObjective();animate();
